const P=window.PhotoPosts,postBasePrepare=C.prepare,postBaseVisible=C.visiblePhotos,postBaseMy=myPage,postBaseCards=albumCards,postBasePhoto=photoPage;
C.prepare=function(s){postBasePrepare(s);P.prepare(s);};C.prepare(state);
C.visiblePhotos=function(s,id=0){return P.sorted(postBaseVisible(s,id));};
function postCaption(p){return (p.caption?'<p class="photo-caption">'+esc(p.caption)+'</p>':'')+(p.authorLabel?'<p class="mini-note">投稿：'+esc(p.authorLabel)+' ／ '+esc((p.created||'').slice(0,10))+'</p>':'');}
// Add comments beside each individual gallery card without changing its navigation.
albumCards=function(photos){return photos.map(p=>{const box=document.createElement('div');box.innerHTML=postBaseCards([p]);if(p.caption||p.authorLabel){const card=box.querySelector('.album-card');if(card)card.insertAdjacentHTML('beforeend',postCaption(p));}return box.innerHTML;}).join('');};
photoPage=function(id){const p=C.visiblePhotos(state).find(p=>p.id===Number(id));if(!p)return frame(title('PHOTO ALBUM','公開中の写真がありません。'));const box=document.createElement('div');box.innerHTML=postBasePhoto(id);box.querySelector('.panel')?.insertAdjacentHTML('beforeend',postCaption(p));return box.innerHTML;};
function photoPostingForm(){const u=current();try{P.member(state,u?.id);}catch(e){return '<section class="panel"><h2>写真を投稿する</h2><p>'+esc(e.message)+'</p></section>';}const a=P.album(state);return '<section class="panel" id="photo-post"><div class="eyebrow">SHARE YOUR PHOTOS</div><h2>最近の一枚、みんなに届けよう。</h2><p>写真とコメントは「'+esc(a.name)+'」へ自動掲載します。</p><form id="photoPostForm" data-key="'+crypto.randomUUID()+'">'+field('title','写真のタイトル')+field('author','アルバムに表示する投稿者名（ニックネーム可）')+'<label class="field">写真についてのコメント<textarea name="caption" maxlength="1000" rows="4"></textarea></label><label class="file-drop">写真を選択（JPEG／PNG・1回10枚まで）<input name="photo" type="file" multiple accept="image/jpeg,image/png" required></label><label class="photo-consent"><input name="consent" type="checkbox" value="yes" required> 写真・コメント・投稿者名の掲載に同意します。</label><p class="mini-note">公開サンプルでは架空の画像のみ使用してください。保存はこのブラウザー内だけで、他端末には共有されません。1人50枚まで。元画像は1枚30MB・3200万画素以内。掲載用に長辺2000pxのJPEGへ縮小します。元画像は保管しません。複数枚のタイトルは連番、コメントは共通です。</p><p class="error-text" role="alert"></p><button class="btn">写真とコメントを投稿する</button></form><p><a href="#/gallery/'+a.id+'">みんなの投稿写真を見る ↗</a></p></section>';}
myPage=function(){return postBaseMy()+(current()?frame(photoPostingForm()):'');};
function photoEditor(p){if(p.deleted)return '<article class="panel"><h3>#'+p.id+' '+esc(p.title)+'</h3><p>削除済み・配信停止</p><form id="photoRestore-'+p.id+'" data-photo="restore" data-id="'+p.id+'">'+field('reason','復元理由')+'<p class="error-text"></p><button class="btn btn-outline">非公開で復元</button></form></article>';return '<article class="panel photo-editor"><h3>#'+p.id+' '+esc(p.title)+'</h3><p>登録者（幹事のみ表示）：'+esc(state.people.find(u=>u.id===p.ownerId)?.name||'幹事の見本画像')+' ／ '+(p.submitted?'参加者の投稿':'幹事の登録')+'</p><img class="post-photo-preview" src="'+esc(p.src)+'" alt="'+esc(p.title)+'"><form id="photoEdit-'+p.id+'" data-photo="edit" data-id="'+p.id+'">'+field('title','写真のタイトル',p.title)+field('author','投稿者名（アルバム表示用）',p.authorLabel||'幹事会')+'<label class="field">写真についてのコメント<textarea name="caption" maxlength="1000" rows="4">'+esc(p.caption)+'</textarea></label>'+albumPicker(p.albumId)+field('sortOrder','表示順（小さい順／同順は新しい投稿が先）',p.sortOrder,'number')+select('published','写真の公開',[['yes','公開'],['no','非公開']],p.published?'yes':'no')+field('reason','処理理由')+'<p class="error-text"></p><button class="btn">写真・コメント・表示順を保存</button></form><form id="photoRemove-'+p.id+'" data-photo="remove" data-id="'+p.id+'">'+field('reason','削除理由')+'<p class="error-text"></p><button class="btn btn-outline">写真を削除（掲載取り下げ）</button></form></article>';}
photosAdmin=function(){return adminShell('photos','<div class="panel"><h2>アルバムに、好きな名前を。</h2><p>名前やアルバム数は自由に設定できます。「みんなの投稿写真」は参加者の投稿先です。名前を変えても投稿先の設定は続きます。</p><h3>アルバムを追加</h3>'+albumForm()+'</div>'+state.albums.map(a=>'<details class="panel" open><summary>'+esc(a.name)+' ／ '+(a.visible?'表示':'非表示')+'</summary>'+albumForm(a)+'</details>').join('')+'<div class="panel"><h3>幹事から写真を登録</h3><div id="uploadAlbumChoice">'+albumPicker()+'</div><label class="file-drop">JPEG／PNGの見本画像（1枚5MB・1回4枚まで）<input id="photoFiles" type="file" accept="image/jpeg,image/png" multiple></label></div><section class="section"><h2>写真・投稿コメントの編集</h2><p>削除は掲載取り下げです。履歴を残し、非公開で復元できます。</p>'+state.photos.slice().sort((a,b)=>Number(a.deleted)-Number(b.deleted)||(a.sortOrder||0)-(b.sortOrder||0)||b.id-a.id).map(photoEditor).join('')+'</section>');};
async function postImage(file){const jpeg=await AlbumUX.resizeFile(file);return {src:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('画像を保存できません。'));r.readAsDataURL(jpeg);})};}
document.addEventListener('submit',async ev=>{const f=ev.target;if(f.id!=='photoPostForm'&&!f.dataset.photo)return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f)),button=f.querySelector('button');const originalLabel=button.textContent;button.disabled=true;try{const u=current();if(!u)throw new Error('ログインが必要です。');if(f.id==='photoPostForm'){P.member(state,u.id);const files=Array.from(f.elements.photo.files);if(!files.length||files.length>10)throw new Error('1回に1〜10枚まで選択してください。');const images=[];for(let i=0;i<files.length;i++){button.textContent=(i+1)+' / '+files.length+'枚を調整中…';images.push(await postImage(files[i]));}change(s=>images.forEach((image,i)=>P.submit(s,{...d,title:files.length>1?d.title.slice(0,175)+'（'+(i+1)+'/'+files.length+'）':d.title,postKey:f.dataset.key+':'+i},image,u.id)));location.hash='/gallery/'+P.album(state).id;}else{const id=Number(f.dataset.id);if(f.dataset.photo==='edit')change(s=>P.edit(s,id,{...d,albumId:d.albumId},u.id));if(f.dataset.photo==='remove')change(s=>P.remove(s,id,d.reason,u.id));if(f.dataset.photo==='restore')change(s=>P.restore(s,id,d.reason,u.id));}route();toast('写真とコメント・操作履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;button.disabled=false;button.textContent=originalLabel;}},true);
route();
